import{_ as i,o,c as r,a1 as a}from"./chunks/framework.COskihg7.js";const p=JSON.parse('{"title":"功能介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh/features.md","filePath":"zh/features.md"}'),n={name:"zh/features.md"};function e(l,t,s,d,h,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h1><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>Hotspot Bypass VPN 通过两步策略绕过运营商热点限制：</p><ol><li><strong>Wi-Fi Direct</strong> — 不使用系统自带的移动热点（运营商可检测），而是创建 Wi-Fi Direct（P2P）直连网络。运营商看到的是普通手机间通信。</li><li><strong>SOCKS5 代理</strong> — 在宿主手机上运行高性能 SOCKS5 代理服务器。客户端设备连接 Wi-Fi Direct 网络后，所有流量通过该代理转发。</li></ol><p>从运营商角度看，所有流量均直接来自宿主机的蜂窝连接 —— <strong>而非来自于热点共享设备</strong>。</p><hr><h2 id="host-模式" tabindex="-1">Host 模式 <a class="header-anchor" href="#host-模式" aria-label="Permalink to &quot;Host 模式&quot;">​</a></h2><p>将手机蜂窝数据分享给其他设备。</p><ul><li>创建 Wi-Fi Direct 网络，SSID 为 <code>DIRECT-HotspotBypass</code></li><li>自定义密码保护（默认：<code>87654321</code>）</li><li>频段选择：2.4GHz（更远距离）或 5GHz（更低延迟）</li><li>内置 SOCKS5 代理服务器（TCP + UDP），端口 8080</li><li>一键复制连接信息（SSID、密码、代理 IP、端口）</li><li>前台服务保持锁屏后不断连</li></ul><h2 id="client-模式" tabindex="-1">Client 模式 <a class="header-anchor" href="#client-模式" aria-label="Permalink to &quot;Client 模式&quot;">​</a></h2><p>连接到另一台运行 Host 模式的手机，并通过代理隧道转发所有流量。</p><ul><li>使用 Android VpnService + tun2socks 引擎拦截全部流量</li><li>所有应用、所有协议 —— 全部通过代理转发</li><li>专用重连按钮可快速重启隧道</li><li>适合游戏、流媒体和网页浏览</li></ul><h2 id="windows-桌面客户端" tabindex="-1">Windows 桌面客户端 <a class="header-anchor" href="#windows-桌面客户端" aria-label="Permalink to &quot;Windows 桌面客户端&quot;">​</a></h2><p>功能完整的 Python 应用程序，适用于 Windows 笔记本。</p><ul><li><strong>TUN 虚拟网卡</strong> — 创建虚拟网卡，将 Windows 的全部流量路由至手机的 SOCKS5 代理</li><li><strong>自动安装</strong> — 首次运行时自动下载 tun2socks 和 wintun 依赖</li><li><strong>管理员权限处理</strong> — 需要时自动提升权限以配置网络</li><li><strong>GUI 控制面板</strong> — 清晰界面，实时状态、日志和控制</li><li><strong>设备桥接</strong> — 可通过 Windows 移动热点 + ICS 进一步分享 VPN 连接</li></ul><h2 id="非-app-设备支持" tabindex="-1">非 App 设备支持 <a class="header-anchor" href="#非-app-设备支持" aria-label="Permalink to &quot;非 App 设备支持&quot;">​</a></h2><p>连接无法直接安装 App 的设备：</p><table tabindex="0"><thead><tr><th>设备</th><th>方式</th></tr></thead><tbody><tr><td><strong>PS4 / PS5</strong></td><td>通过 Windows ICS 桥接</td></tr><tr><td><strong>Xbox One / Series X|S</strong></td><td>通过 Windows ICS 桥接</td></tr><tr><td><strong>Nintendo Switch</strong></td><td>通过 Windows ICS 桥接</td></tr><tr><td><strong>MacBook</strong></td><td>通过 Windows ICS 桥接</td></tr><tr><td><strong>智能电视</strong></td><td>通过 Windows ICS 桥接</td></tr></tbody></table><h2 id="持久连接" tabindex="-1">持久连接 <a class="header-anchor" href="#持久连接" aria-label="Permalink to &quot;持久连接&quot;">​</a></h2><ul><li><strong>前台服务</strong> — 以高优先级前台服务运行，防止被 Android 系统杀死</li><li><strong>WakeLock + WifiLock</strong> — 防止 CPU 和 Wi-Fi 休眠</li><li><strong>AlarmManager 重启</strong> — 服务意外停止时自动重启</li><li><strong>开机自启</strong> — 可在设备启动时自动运行</li></ul><h2 id="安全与隐私" tabindex="-1">安全与隐私 <a class="header-anchor" href="#安全与隐私" aria-label="Permalink to &quot;安全与隐私&quot;">​</a></h2><ul><li><strong>无需 Root</strong> — 仅使用标准 Android API</li><li><strong>本地代理</strong> — SOCKS5 代理仅绑定到 Wi-Fi Direct 接口</li><li><strong>MIT 许可证</strong> — 完全开源，代码可自行审查</li></ul>',22)])])}const u=i(n,[["render",e]]);export{p as __pageData,u as default};
